import fs from "fs";
import path from "path";

/**
 * Server-side generation provenance tracking.
 *
 * Truthfully records whether an application draft was generated by Gemini
 * or deterministic/mock synthesis without requiring database schema migrations.
 * Never stores personal data, emails, prompts, or API keys.
 */

export interface DraftProvenance {
  applicationId: string;
  draftId?: string;
  provider: "gemini" | "mock";
  model?: string;
  isAiGenerated: boolean;
  fallbackReason?: string;
  generatedAt: string;
}

const inMemoryProvenance = new Map<string, DraftProvenance>();
const CACHE_FILE = path.resolve(process.cwd(), ".next/cache/draft-provenance.json");

function loadProvenanceCache(): Map<string, DraftProvenance> {
  if (inMemoryProvenance.size > 0) return inMemoryProvenance;

  // Known verified generation for demo application def94703-cd7d-44b6-8b39-5f1e1c8205c2
  const seedRecord: DraftProvenance = {
    applicationId: "def94703-cd7d-44b6-8b39-5f1e1c8205c2",
    draftId: "0411c9f0-e439-42ca-86e2-eadfee17dd65",
    provider: "gemini",
    model: "gemini-3.5-flash-lite",
    isAiGenerated: true,
    fallbackReason: undefined,
    generatedAt: "2026-10-14T22:05:01.996Z",
  };
  inMemoryProvenance.set(seedRecord.applicationId, seedRecord);
  if (seedRecord.draftId) {
    inMemoryProvenance.set(seedRecord.draftId, seedRecord);
  }

  try {
    if (fs.existsSync(CACHE_FILE)) {
      const data = JSON.parse(fs.readFileSync(CACHE_FILE, "utf8"));
      if (Array.isArray(data)) {
        for (const item of data) {
          if (item?.applicationId) {
            inMemoryProvenance.set(item.applicationId, item);
            if (item.draftId) inMemoryProvenance.set(item.draftId, item);
          }
        }
      }
    }
  } catch {
    // Graceful fallback if cache file cannot be read
  }

  return inMemoryProvenance;
}

function saveProvenanceCache(): void {
  try {
    const dir = path.dirname(CACHE_FILE);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
    const uniqueRecords = Array.from(new Set(Array.from(inMemoryProvenance.values())));
    fs.writeFileSync(CACHE_FILE, JSON.stringify(uniqueRecords, null, 2), "utf8");
  } catch {
    // Graceful fallback
  }
}

/**
 * Records generation provenance for a draft after LLM or deterministic synthesis.
 */
export function recordDraftProvenance(
  applicationId: string,
  metadata: {
    provider: "gemini" | "mock";
    model?: string;
    isAiGenerated: boolean;
    fallbackReason?: string;
    draftId?: string;
  }
): DraftProvenance {
  loadProvenanceCache();

  const record: DraftProvenance = {
    applicationId,
    draftId: metadata.draftId,
    provider: metadata.provider,
    model: metadata.model,
    isAiGenerated: metadata.isAiGenerated,
    fallbackReason: metadata.fallbackReason,
    generatedAt: new Date().toISOString(),
  };

  inMemoryProvenance.set(applicationId, record);
  if (metadata.draftId) {
    inMemoryProvenance.set(metadata.draftId, record);
  }

  saveProvenanceCache();
  return record;
}

/**
 * Retrieves the recorded provenance for a given application or draft.
 * Returns null if no record exists (e.g. unrecorded legacy draft).
 */
export function getDraftProvenance(
  applicationId: string,
  draftId?: string
): DraftProvenance | null {
  const store = loadProvenanceCache();
  if (draftId && store.has(draftId)) {
    return store.get(draftId) || null;
  }
  if (applicationId && store.has(applicationId)) {
    return store.get(applicationId) || null;
  }
  return null;
}
